/**
 * @file CongruenceSetup.cpp
 * @brief Setup builder of the station congruence census.
 */
#include "network/qc/CongruenceSetup.hpp"
#include "network/driver/Run.hpp"
#include "network/state/RunContext.hpp"
#include "network/driver/SetupResult.hpp"
#include "config/GnssConfig.hpp"
#include "network/diag/RunTraces.hpp"
#include "network/qc/Congruence.hpp"

namespace GnssProcessor {

// Setup builder; documented at its declaration in network/qc/CongruenceSetup.hpp.
void networkCongruenceArm(NetworkRun& run) {
    // ---- From the run (generated by scripts/nom_ep4_cut.py, each line
    //      checked by scripts/nom_ep4_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    // ---- End of the bindings ----
    // Station congruence.  Seated here for the block census's reason (its feed
    // site is inside the redundancy-census seam), with no resolver to install:
    // the INC-3 separability join reads the block census's own hit count at the
    // sweep site, not an injected callback.  An unarmed run keeps the
    // default-constructed unarmed instance.
    if (ctx.knobs.cg_on)
        ctx.carry.cg = NetworkCongruence(/*armed=*/true, kCongruenceWindowEpochs,
                                         kCongruenceWarmupSamples,
                                         ctx.knobs.cg_report_sigma);
}

} // namespace GnssProcessor
